# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student


def _student(last, section="A", email="x@y.org"):
    return Student("1", last, "Pat", section, email)


class ContactRowTests(unittest.TestCase):
    def test_rows_are_sorted_and_aligned(self):
        rows = contact_rows(
            [
                _student("Zed", "B", "z@y.org"),
                _student("Adams", "A", "a@y.org"),
            ]
        )
        self.assertEqual(
            rows,
            [
                "Adams, Pat  A  a@y.org",
                "Zed, Pat    B  z@y.org",
            ],
        )

    def test_missing_email_names_student(self):
        with self.assertRaisesRegex(ProjectError, "Zed, Pat"):
            contact_rows([_student("Zed", email=None)])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
